(function(root){'use strict';root.MT_WORKSPACE_APP.register({analysis:c=>({html:'<h1>Experiments & comparison</h1><p class="next-intro">Predict a change, explore the model and compare two captured scenarios. Open Save, compare & analyse inside any experiment to retain a project case, rank sensitivities or calculate a two-input map.</p><section class="panel"><label>Filter by task or topic<input id="analysis-find" type="search" placeholder="pump, stress, motor, navigation…"></label><div id="analysis-modules"></div></section>',bind(){function show(){const query=c.$('analysis-find').value.toLowerCase();c.$('analysis-modules').innerHTML=c.modules.filter(m=>(m.title+' '+m.group).toLowerCase().includes(query)).map(m=>'<article class="next-step"><h2>'+c.esc(m.title)+'</h2><p>'+c.esc(m.group)+' · Chapter '+m.chapter+'</p><a href="students/'+c.esc(m.url.split('#')[0])+'?analysis=1#'+c.esc(m.url.split('#')[1]||'')+'">Open model and analysis →</a></article>').join('')||c.empty('No matching experiments.');}c.on('analysis-find','input',show);show();}})});})(window);
